CREATE DATABASE IF NOT EXISTS meeting_tracker;USE meeting_tracker;CREATE TABLE IF NOT EXISTS meetings(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,meeting_date DATE,notes TEXT NOT NULL,summary TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS action_items(id INT AUTO_INCREMENT PRIMARY KEY,meeting_id INT NOT NULL,task TEXT NOT NULL,owner VARCHAR(150),status VARCHAR(30) DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(meeting_id) REFERENCES meetings(id) ON DELETE CASCADE);